import json
import re
import shutil
from collections import Counter
from pathlib import Path
from urllib.parse import unquote

from markdown_it import MarkdownIt


ROOT = Path(__file__).resolve().parents[1]
SOURCE = ROOT / "references/27李林880/md/【做题本】平板版27考研李林辅导讲义（高数）.md"
WORK = ROOT / ".question-bank-work"
OUTPUT = ROOT / "output"
TARGET = OUTPUT / "李林高数上册分节题集.tex"
FORMULAS = re.compile(r"\\\(([\s\S]*?)\\\)|\\\[([\s\S]*?)\\\]|(?<!\\)(\$\$|\$)([\s\S]*?)(?<!\\)\3")
SECTIONS = {
    "1.1": "集合、映射与函数", "1.2": "数列的极限", "1.3": "函数的极限",
    "1.4": "无穷小量与无穷大量", "1.5": "连续函数",
    "2.1": "导数的概念", "2.2": "求导的基本法则", "2.3": "微分",
    "2.4": "微分中值定理及其应用", "2.5": "Taylor定理及其应用", "2.6": "函数性态的研究",
    "3.1": "定积分的概念、存在条件与性质", "3.2": "微积分基本公式与基本定理",
    "3.3": "两种基本积分法", "3.4": "定积分的应用", "3.5": "反常积分",
    "4.1": "几类简单的微分方程", "4.2": "高阶线性微分方程", "4.3": "线性微分方程组",
}
CHAPTERS = {
    "1": "函数、极限、连续", "2": "一元函数微分学及其应用",
    "3": "一元函数积分学及其应用", "4": "常微分方程",
}


def read_questions():
    questions = {}
    chapter = group = ""
    current = None
    for number, line in enumerate(SOURCE.read_text().splitlines(), 1):
        if line.startswith("## "):
            chapter = line.removeprefix("## ").strip()
            group = "示例"
            current = None
        elif line.startswith("### "):
            group = line.removeprefix("### ").strip()
            current = None
        elif line.startswith("#### "):
            current = number
            questions[number] = {
                "line": number, "chapter": chapter, "group": group,
                "label": line.removeprefix("#### ").strip(), "body": [],
                "pdf_page": len(questions) + 2,
            }
        elif current is not None:
            questions[current]["body"].append(line)
    for question in questions.values():
        question["body"] = "\n".join(question["body"]).strip()
    assert len(questions) == 746
    return questions


def read_solutions(questions):
    solutions = {}
    for path in sorted(WORK.glob("lilin-ipad-*.txt")):
        for match in re.finditer(r"^@@ (\d+) (\S+)\n([\s\S]*?)(?=^@@ |\Z)", path.read_text(), re.M):
            line, section, text = int(match[1]), match[2], match[3].strip()
            assert line in questions and line not in solutions, (path, line)
            assert section in SECTIONS or section == "skip", (line, section)
            assert text, line
            solutions[line] = {"section": section, "solution": text}
    return solutions


def tex_text(text):
    text = normalize_numbers(text)
    replacements = {"\\": r"\textbackslash{}", "&": r"\&", "%": r"\%",
                    "#": r"\#", "_": r"\_", "{": r"\{", "}": r"\}",
                    "^": r"\textasciicircum{}", "~": r"\textasciitilde{}"}
    return "".join(replacements.get(character, character) for character in text)


def normalize_numbers(text):
    return text.translate(str.maketrans({"Ⅰ": "I", "Ⅱ": "II", "Ⅲ": "III", "Ⅳ": "IV", "Ⅴ": "V", "Ⅵ": "VI"}))


def math_tex(text):
    assert not re.search(r"[\x00-\x08\x0b\x0c\x0e-\x1f]", text), "公式内存在控制字符"
    text = normalize_numbers(text)
    text = text.replace(r"\tfrac", r"\frac").replace(r"\dfrac", r"\frac")
    text = text.replace("≤", r"\le ").replace("≥", r"\ge ").replace("π", r"\pi ")
    text = text.replace("∞", r"\infty ").replace("−", "-").replace("⋯", r"\cdots ")
    text = text.replace(r"\lim\limits", r"\lim")
    text = text.replace(r"x=0\atop y=\pi", r"\substack{x=0\\y=\pi}")
    text = re.sub(r"\{(-?\d+)/(\d+)\}", r"{\\frac{\1}{\2}}", text)
    text = text.replace("^{i/n}", r"^{\frac in}").replace("^{2i/n}", r"^{\frac{2i}n}")
    text = text.replace("$q'/q$", r"$\frac{q'}q$")
    text = text.replace(r"kg/m^{3}", r"\frac{\mathrm{kg}}{\mathrm m^3}")
    text = text.replace(r"m/s^{2}", r"\frac{\mathrm m}{\mathrm s^2}")
    text = text.replace(r"(cm^{3}/s)", r"(\frac{\mathrm{cm}^3}{\mathrm s})")
    text = text.replace(r"(cm^{2}/s)", r"(\frac{\mathrm{cm}^2}{\mathrm s})")
    text = text.replace(r"\rm 矩", r"\text{矩}").replace(r"\rm 下", r"\text{下}")
    return text


def question_tex(body, compact_choices=False):
    stored_math = []

    def protect(match):
        expression = match[1] or match[2] or match[4]
        display = match[2] is not None or match[3] == "$$"
        stored_math.append((display, math_tex(expression.strip())))
        return f"MATHPLACEHOLDER{len(stored_math) - 1}END"

    protected = FORMULAS.sub(protect, body)
    tokens = MarkdownIt("commonmark").parse(protected)
    result = []
    choice = 0
    for token in tokens:
        if compact_choices and token.type == "list_item_open":
            result.append(r"\begin{minipage}[t]{.48\linewidth}")
        elif compact_choices and token.type == "list_item_close":
            choice += 1
            result.append(r"\end{minipage}" + (r"\par\medskip" if choice % 2 == 0 else r"\hfill"))
        elif token.type == "paragraph_close":
            result.append("\n\n")
        elif token.type == "inline":
            for child in token.children:
                if child.type == "text":
                    result.append(tex_text(child.content))
                elif child.type in ("softbreak", "hardbreak"):
                    result.append(" ")
                elif child.type == "code_inline":
                    result.append(r"\underline{\hspace{4em}}" if re.fullmatch(r"_+", child.content)
                                  else r"\texttt{" + tex_text(child.content) + "}")
                elif child.type == "strong_open":
                    result.append(r"\textbf{")
                elif child.type == "strong_close":
                    result.append("}")
                elif child.type == "image":
                    name = unquote(child.attrGet("src"))
                    if "094" in name or "135" in name:
                        continue
                    source_image = SOURCE.parent / name
                    assert source_image.is_file(), name
                    destination = OUTPUT / "lilin-figures" / source_image.name
                    destination.parent.mkdir(exist_ok=True)
                    shutil.copyfile(source_image, destination)
                    width = "390bp" if any(x in name for x in ("208", "212", "221", "304", "311")) else "170bp"
                    result.append(r"\par\smallskip\includegraphics[width=" + width +
                                  r",height=135bp,keepaspectratio]{lilin-figures/" + source_image.name + "}")
                else:
                    assert child.type in ("em_open", "em_close"), child.type
        elif token.type not in ("paragraph_open", "bullet_list_open", "bullet_list_close",
                                "list_item_open", "list_item_close"):
            raise ValueError((token.type, token.content))
    text = "".join(result).strip()
    for index, (display, expression) in enumerate(stored_math):
        text = text.replace(f"MATHPLACEHOLDER{index}END",
                            (r"\[" + expression + r"\]") if display else "$" + expression + "$")
    assert "MATHPLACEHOLDER" not in text
    return text


PREAMBLE = r"""
% !TeX program = xelatex
\documentclass[UTF8,zihao=-4,fontset=fandol]{ctexart}
\usepackage[paperwidth=800bp,paperheight=600bp,left=44bp,right=44bp,top=38bp,bottom=38bp,headsep=16bp,footskip=14bp]{geometry}
\usepackage{amsmath,amssymb,xcolor,fancyhdr,graphicx}
\usepackage[hidelinks,bookmarksopen=true]{hyperref}
\renewcommand{\lim}{\operatorname*{lim}\limits}
\everymath{\displaystyle}
\definecolor{accent}{HTML}{175C57}
\setlength{\parindent}{0pt}
\setlength{\parskip}{6bp}
\setlength{\headheight}{14bp}
\setlength{\abovedisplayskip}{6bp}
\setlength{\belowdisplayskip}{6bp}
\setlength{\emergencystretch}{3em}
\pagestyle{fancy}
\fancyhf{}
\renewcommand{\headrulewidth}{0pt}
\fancyfoot[L]{\footnotesize\color{gray}李林高数 · 上册分节题集 · 4:3 横屏}
\fancyfoot[R]{\footnotesize\thepage}
\raggedbottom
\newcommand{\SectionHeading}[2]{\fancyhead[L]{}\def\CurrentSection{#1\quad #2}
  \hypertarget{s#1}{}\pdfbookmark[1]{#1 #2}{s#1}}
\newcommand{\Question}[2]{\fancyhead[L]{}
  \def\CurrentNumber{#1}\def\CurrentSource{#2}
  {\small\color{accent}\CurrentSection}\par
  {\Large\bfseries 第 #1 题}\hfill{\footnotesize\color{gray}#2}\par\medskip
  \fontsize{13}{23}\selectfont}
\newcommand{\Solution}{\clearpage
  \fancyhead[L]{\footnotesize\color{gray}第 \CurrentNumber\ 题解析}
  \fontsize{12}{20}\selectfont
  {\Large\bfseries 第 \CurrentNumber\ 题解析}\par\medskip}
\newcommand{\TextCorrection}[1]{\par{\small\color{accent}\textbf{题面核对}\quad #1}\par}
\begin{document}
"""


def build():
    questions = read_questions()
    solutions = read_solutions(questions)
    included = {line: record for line, record in solutions.items() if record["section"] != "skip"}
    counts = Counter(record["section"] for record in included.values())
    pieces = [PREAMBLE, r"\pdfbookmark[0]{目录}{contents}",
              r"{\LARGE\bfseries 李林高数上册分节题集}\par",
              r"{\small 按《工科数学分析基础》第三版上册目录编排。题目页下方留空，翻页看对应解析。}",
              r"\par{\small 分式采用上下结构，极限条件置于运算符下方。跨节题按主要解法收录一次。}",
              r"\par{\small 题源沿用讲义原章、组别和题号。题面存在条件冲突时，解析明确给出结论及依据。}",
              r"\par\smallskip\begingroup\setlength{\parskip}{0.5bp}\fontsize{10.8}{12}\selectfont"]
    chapter = None
    for section, title in SECTIONS.items():
        if chapter != section[0]:
            chapter = section[0]
            pieces.append(r"\par\smallskip\textbf{第" + chapter + "章 " + CHAPTERS[chapter] + "}")
        pieces.append(r"\par\hyperlink{s" + section + "}{" + section + r"\quad " + title +
                      r"}\hfill " + str(counts[section]) + " 题")
    pieces.append(r"\par\smallskip{\footnotesize 共 " + str(len(included)) +
                  r" 题。若一题有多个小问，题目页保留全部小问，详解可接续到后一页。}")
    pieces.append(r"\par\endgroup")
    sequence = []
    chapter = None
    for section, title in SECTIONS.items():
        if chapter != section[0]:
            chapter = section[0]
            pieces.append(r"\clearpage\pdfbookmark[0]{第" + chapter + "章 " + CHAPTERS[chapter] + "}{c" + chapter + "}")
        pieces.append(r"\SectionHeading{" + section + "}{" + title + "}")
        rows = [(line, record) for line, record in sorted(included.items()) if record["section"] == section]
        if not rows:
            pieces.append(r"{\Large\bfseries " + section + r"\quad " + title + r"}\par\medskip 本题源中暂无属于本节的完整题目。")
        for line, record in rows:
            question = questions[line]
            body = question["body"]
            corrections = {
                509: [(r"\frac{\mathrm{e}^{ax}+x^2-ax-1}{4x^2}", r"\frac{\mathrm{e}^{ax}+x^2-ax-1}{\frac14x^2}")],
                1508: [(r"\int_{\max}", r"\int\max")],
                1664: [(r"\arcsin(x-1)^2", r"\arcsin((x-1)^2)")],
                1742: [(r"\sin(u-t)^{2}", r"\sin((u-t)^{2})")],
                1868: [(r"\sqrt{1|x-x^2|}", r"\sqrt{|x-x^2|}")],
                1091: [(r"a^{2} f''(x_{0})", r"a^{2} f'''(x_{0})")],
                2812: [(r"y''+ay'+by'+cy=0", r"y'''+ay''+by'+cy=0")],
                2904: [(r"a\geq0,f(t)", r"a>0,f(t)")],
            }
            for before, after in corrections.get(line, []):
                assert before in body, (line, before)
                body = body.replace(before, after)
            body = body.replace("30cm/s", r"$30\frac{\mathrm{cm}}{\mathrm s}$")
            body = body.replace("200 m/s", r"$200\frac{\mathrm m}{\mathrm s}$").replace("80 m/s", r"$80\frac{\mathrm m}{\mathrm s}$")
            if line == 2042:
                body = body.replace("$ (IV)", "$\n\n(IV)").replace("$ (VII)", "$\n\n(VII)")
            source_label = question["chapter"].split(" ", 1)[0] + " · " + question["group"] + " · " + question["label"]
            number = len(sequence) + 1
            pieces.extend([
                f"% SOURCE line={line} pdf_page={question['pdf_page']} section={section}",
                r"\Question{" + str(number) + "}{" + tex_text(source_label) + "}",
                question_tex(body, compact_choices=line == 418), r"\vfill", r"\Solution",
                math_tex(record["solution"]), r"\clearpage",
            ])
            sequence.append({"number": number, "line": line, "section": section, "source": source_label})
    pieces.append(r"\end{document}")
    TARGET.write_text("\n\n".join(pieces) + "\n")
    manifest = {"included": sequence, "counts": dict(counts), "processed": len(solutions),
                "skipped": [{"line": line, **record} for line, record in sorted(solutions.items())
                            if record["section"] == "skip"],
                "unprocessed": [{"line": line, "chapter": q["chapter"], "label": q["label"]}
                                for line, q in questions.items() if line not in solutions]}
    (WORK / "lilin-ipad-manifest.json").write_text(json.dumps(manifest, ensure_ascii=False, indent=2) + "\n")
    print(json.dumps({"questions": len(sequence), "processed": len(solutions), "counts": dict(counts)}, ensure_ascii=False))


if __name__ == "__main__":
    build()

