const fs = require("node:fs");
const katex = require("./proof-katex/node_modules/katex");

const formulas = /\\\(([\s\S]*?)\\\)|\\\[([\s\S]*?)\\\]|(?<!\\)(\$\$|\$)([\s\S]*?)(?<!\\)\3/g;
let count = 0;
const errors = [];
for (const line of fs.readFileSync(process.argv[2], "utf8").trim().split("\n")) {
  const { page, text } = JSON.parse(line);
  for (const match of text.matchAll(formulas)) {
    const expression = match[1] ?? match[2] ?? match[4];
    try {
      katex.renderToString(expression, { throwOnError: true, strict: "ignore" });
      count++;
    } catch (error) {
      errors.push({ page, expression, error: error.message });
    }
  }
  if (/\\[()[\]]|(?<!\\)\$/.test(text.replace(formulas, ""))) {
    errors.push({ page, error: "Unpaired math delimiters" });
  }
}
console.log(JSON.stringify({ count, errors }, null, 2));
if (process.argv.includes("--require-clean") && errors.length > 0) {
  process.exitCode = 1;
}
